from modele import chapitre,E,Q,tableau

chapitre(7,'proportionnalite','Proportionnalité et pourcentages','2 · Algèbre et modèles',
'Passage à l’unité · Quatrième proportionnelle · Échelles',
['Reconnaître une relation proportionnelle.','Calculer une quatrième proportionnelle avec plusieurs méthodes.','Utiliser pourcentages, échelles et formules.'],
['Fractions et calculs décimaux.'],[
r'''\essSection{1}{Reconnaître et calculer}
\begin{definition}Deux grandeurs sont proportionnelles si l’on passe des valeurs de la première à celles de la seconde en multipliant toujours par le même nombre, le coefficient de proportionnalité. Les unités et le sens du passage doivent être précisés.\end{definition}
\begin{exemple}Si 4 cahiers identiques coûtent 10 euros sans frais fixes, un cahier coûte $10/4=2{,}50$ euros. Pour 7 cahiers, on paie $7\times2{,}50=17{,}50$ euros. On peut aussi calculer directement $7\times10/4$.\end{exemple}
\begin{propriete}Dans un tableau proportionnel, on peut multiplier une colonne par un nombre ou additionner des colonnes. Pour deux couples $(a,b)$ et $(c,d)$ proportionnels, $ad=bc$ : les produits en croix sont égaux.\end{propriete}
\begin{attention}Une hausse régulière ne suffit pas : un tarif de 5 euros fixes plus 2 euros par article n’est pas proportionnel. Des points alignés doivent aussi être alignés avec l’origine pour représenter une proportionnalité.\end{attention}''',
r'''\essSection{2}{Appliquer dans plusieurs contextes}
\begin{propriete}Prendre $p\,\%$ d’une quantité revient à la multiplier par $p/100$. Pour trouver un pourcentage, diviser la partie par le total, puis multiplier par 100. Une baisse de 20\,\% retire 20\,\% de la valeur de départ de cette baisse.\end{propriete}
\begin{definition}Une échelle est le rapport longueur représentée sur longueur réelle, mesurées dans la même unité. À l’échelle $1/200$, 1 cm sur le plan représente 200 cm en réalité.\end{definition}
\begin{exemple}Sur 80 élèves, 28 prennent le bus : $28/80=0{,}35$, soit 35\,\%. Un article de 60 euros baissé de 15\,\% perd $0{,}15\times60=9$ euros et coûte donc 51 euros.\end{exemple}
\begin{savoirfaire}[Lire une formule]Si une résistance vaut $R=8\ \Omega$ et si $U=RI$, alors $U=8I$ : tension et intensité sont proportionnelles dans ce modèle. Pour un cercle, $L=\pi d$ relie aussi deux grandeurs proportionnelles, la circonférence et le diamètre.\end{savoirfaire}
\begin{attention}Pour deux pourcentages successifs, identifier la nouvelle base à chaque étape. On ne les additionne pas automatiquement. Les méthodes de ce chapitre reposent sur des parts et des tableaux ; le vocabulaire de fonction linéaire n’est pas nécessaire.\end{attention}'''],[
E('Passer à l’unité',r"Six bouteilles identiques coûtent 9 euros. Combien coûtent dix bouteilles, sans frais fixes ?",r"Une bouteille coûte $9/6=1{,}50$ euro. Dix bouteilles coûtent $10\times1{,}50=\res{15}$ euros. On suppose le prix unitaire constant.","Calculer le prix d’une unité.","assert Rational(9,6)*10==15"),
E('Compléter un tableau',r"Le prix est proportionnel à la masse. Compléter le tableau."+tableau(['Masse (kg)','2','5','8'],[['Prix (euros)','7','?','?']]),r"Le coefficient masse vers prix est $7/2=3{,}5$ euros par kg. Les prix sont donc $5\times3{,}5=\res{17{,}50}$ euros et $8\times3{,}5=\res{28}$ euros.","Préciser le sens du coefficient.","assert 5*Rational(7,2)==Rational('17.5') and 8*Rational(7,2)==28"),
E('Une part en pourcentage',r"Calculer 18\,\% de 250.",r"$18\,\%=18/100$. La part cherchée vaut $(18/100)\times250=\res{45}$.","Multiplier la quantité par la fraction correspondante.","assert Rational(18,100)*250==45"),
E('Retrouver le pourcentage',r"Dans un groupe de 32 élèves, 12 sont demi-pensionnaires. Quel pourcentage cela représente-t-il ?",r"Le rapport partie sur total est $12/32=0{,}375$. Il correspond à $\res{37{,}5\,\%}$. Le dénominateur est l’effectif total, pas celui des autres élèves.","Diviser la partie par le total.","assert Rational(12,32)*100==Rational('37.5')"),
E('Lire une échelle',r"Sur un plan à l’échelle $1/500$, un mur mesure 3,6 cm. Quelle longueur réelle représente-t-il en mètres ?",r"La longueur réelle est $3{,}6\times500=1800$ cm, soit $\res{18\ \mathrm m}$. La conversion en mètres vient après le calcul dans la même unité.","Faire d’abord le rapport avec des unités identiques.","assert Rational('3.6')*500/100==18"),
E('Une quatrième proportionnelle',r"Huit pièces identiques pèsent 14,4 kg. Quelle est la masse de cinq pièces ? Donner deux méthodes.",r"Par unité : $14{,}4/8=1{,}8$ kg, puis $5\times1{,}8=\res9$ kg. Directement, on calcule $5\times14{,}4/8=9$ kg. Les deux méthodes utilisent le même prix de passage, ici une masse unitaire.","Comparer passage à l’unité et calcul direct.","assert 5*Rational('14.4')/8==9"),
E('Une remise',r"Un sac coûte 80 euros. On lui applique une remise de 12\,\%. Quel est son nouveau prix ?",r"La remise vaut $80\times12/100=9{,}60$ euros. On la retire : $80-9{,}60=\res{70{,}40}$ euros. Une remise est une diminution.","Calculer la baisse avant le prix final.","assert 80*(1-Rational(12,100))==Rational('70.4')"),
E('Un tarif non proportionnel',r"Un service facture 4 euros fixes puis 3 euros par heure. Calculer pour 1 h et 2 h. Le prix est-il proportionnel au temps ?",r"Pour 1 h : $4+3=\res7$ euros. Pour 2 h : $4+6=\res{10}$ euros. Doubler le temps ne double pas 7 euros, donc il n’y a pas proportionnalité. Les frais fixes l’empêchent.","Tester un doublement.","assert 4+3==7 and 4+3*2==10 and 10!=2*7"),
E('Un graphique',r"Le graphique représente un prix en fonction d’une masse. Reconnaître la proportionnalité et lire le prix de 3 kg.",r"Les points sont sur une droite passant par l’origine, ce qui représente une proportionnalité dans ce modèle. À 3 kg, l’ordonnée est $\res{7{,}50}$ euros. Le coefficient est 2,50 euros par kg.","Vérifier l’alignement avec l’origine puis lire les axes.","assert 3*Rational('2.5')==Rational('7.5')",figure='proportion-prix'),
E('Une formule en sciences',r"Dans le modèle $U=RI$, $R=15\ \Omega$. Calculer $U$ pour $I=0{,}4$ A, puis $I$ quand $U=9$ V.",r"$U=15\times0{,}4=\res6$ V. Pour 9 V, $9=15I$, donc $I=9/15=\res{0{,}6}$ A. Le coefficient tension sur intensité est constant et vaut 15.","Isoler la grandeur cherchée dans la formule.","assert 15*Rational('.4')==6 and Rational(9,15)==Rational('.6')"),
E('Deux remises successives',r"Un article de 100 euros subit une baisse de 20\,\%, puis de 10\,\% du nouveau prix. Quel prix obtient-on ? La baisse totale vaut-elle 30\,\% ?",r"Après 20\,\%, le prix est 80 euros. La seconde baisse vaut $10\,\%$ de 80, soit 8 euros : le prix final est $\res{72}$ euros. La baisse totale vaut 28 euros sur 100, donc $\res{28\,\%}$, et non 30\,\%.","Changer de base pour la seconde remise.","assert 100*(1-Rational(20,100))*(1-Rational(10,100))==72"),
E('Une recette et des lots',r"Une recette pour 6 personnes demande 450 g de farine. On la prépare pour 14 personnes. La farine est vendue en paquets de 500 g. Combien de paquets faut-il ?",r"Par personne, il faut $450/6=75$ g. Pour 14 personnes, $75\times14=1050$ g. Deux paquets ne donnent que 1000 g : il faut $\res3$ paquets. La quantité achetée peut dépasser la quantité nécessaire.","Calculer la quantité puis arrondir le nombre de lots vers le haut.","assert 450*Rational(14,6)==1050 and ceil(Rational(1050,500))==3"),
E('Un pourcentage inverse',r"Après une remise de 25\,\%, un objet coûte 54 euros. Retrouver son prix avant remise.",r"Le prix payé représente 75\,\% du prix initial $P$. On écrit $(75/100)P=54$, d’où $P=54\times100/75=\res{72}$ euros. Vérification : 25\,\% de 72 vaut 18, et $72-18=54$.","Identifier la part conservée du prix initial.","assert Rational(54)/Rational(75,100)==72"),
E('Un arc de cercle',r"Un cercle de rayon 6 cm porte un arc de mesure $75^\circ$. Calculer la longueur de cet arc, exactement puis au dixième de cm.",r"La circonférence vaut $2\pi\times6=12\pi$ cm. L’arc en représente $75/360$, donc sa longueur vaut $12\pi\times75/360=\res{5\pi/2\ \mathrm{cm}}$, soit environ $\res{7{,}9\ \mathrm{cm}}$.","Prendre la fraction d’un tour complet.","assert simplify(12*pi*Rational(75,360))==5*pi/2 and round(float(5*pi/2),1)==7.9",figure='arc-75'),
E('Deux groupes réunis',r"Un club compte 20 jeunes dont 40\,\% de filles, et 30 adultes dont 60\,\% de femmes. Quel est le pourcentage de personnes de sexe féminin dans le club ?",r"Il y a $20\times0{,}4=8$ filles et $30\times0{,}6=18$ femmes, soit 26 personnes sur 50. Le pourcentage est $26/50\times100=\res{52\,\%}$. La moyenne simple de 40\,\% et 60\,\% ignorerait les effectifs différents.","Revenir aux effectifs avant de réunir les groupes.","assert (20*Rational(40,100)+30*Rational(60,100))/50==Rational(52,100)")
],reperes=['Quatrième proportionnelle et méthodes','Pourcentages directs et inverses','Échelles et formules proportionnelles','Graphiques et proportionnalité'],deco='courbe')

chapitre(8,'grandeurs','Grandeurs composées et unités','2 · Algèbre et modèles',
'Vitesse · Débit · Concentration · Énergie',
['Calculer une grandeur quotient ou produit.','Convertir les unités de temps, de volume et de vitesse.','Contrôler la cohérence d’une formule et d’un résultat.'],
['Proportionnalité et conversions simples.'],[
r'''\essSection{1}{Des quotients de grandeurs}
\begin{definition}Une vitesse moyenne est une distance divisée par une durée : $v=d/t$. Un débit est un volume divisé par une durée : $q=V/t$. Une concentration massique est une masse de substance divisée par le volume de solution : $c=m/V$. Une masse volumique est la masse totale d’une matière divisée par son volume : $\rho=m/V$.\end{definition}
\begin{exemple}Parcourir 150 km en 2 h 30 min donne $t=2{,}5$ h, puis $v=150/2{,}5=60$ km/h. Un robinet débitant 12 L en 40 s a un débit de $12/40=0{,}3$ L/s.\end{exemple}
\begin{savoirfaire}[Choisir des unités cohérentes]Pour des km/h, utiliser des km et des heures. Pour des m/s, utiliser des mètres et des secondes. $1$ h $=3600$ s, $1$ min $=60$ s. Attention : 1 h 30 min vaut 1,5 h, pas 1,30 h.\end{savoirfaire}
\begin{attention}La vitesse moyenne d’un aller-retour n’est pas en général la moyenne des deux vitesses. Il faut toujours diviser la distance totale par la durée totale.\end{attention}''',
r'''\essSection{2}{Convertir des grandeurs composées}
\begin{propriete}$1$ km/h $=1000/3600$ m/s $=1/3{,}6$ m/s. Pour passer de km/h à m/s, diviser par 3,6 ; dans l’autre sens, multiplier par 3,6. Cette règle se retrouve avec les conversions de distance et de temps.\end{propriete}
\begin{propriete}$1$ L $=1$ dm$^3$, $1$ m$^3=1000$ L et $1$ mL $=1$ cm$^3$. Par exemple $0{,}02$ m$^3$/s $=20$ L/s $=1200$ L/min : on convertit séparément volume et temps.\end{propriete}
\begin{definition}Une grandeur produit se calcule en multipliant deux grandeurs. Par exemple, à puissance constante, l’énergie est $E=P\times t$. Avec $P$ en kW et $t$ en h, $E$ est en kWh. Les formules scientifiques utiles sont données dans les exercices.\end{definition}
\begin{savoirfaire}[Contrôler]Écrire les unités à côté des données avant le calcul. Vérifier si une augmentation doit faire augmenter ou diminuer le résultat : pour un même volume, un débit plus fort donne une durée plus courte. Donner un ordre de grandeur et une phrase avec l’unité finale.\end{savoirfaire}'''],[
E('Une durée',r"Convertir 2 h 18 min en heures décimales et en minutes.",r"$18$ min $=18/60=0{,}3$ h, donc la durée vaut $\res{2{,}3\ \mathrm h}$. En minutes : $2\times60+18=\res{138}$ min.","Utiliser une heure de 60 minutes.","assert 2+Rational(18,60)==Rational('2.3') and 2*60+18==138"),
E('Une vitesse moyenne',r"Un cycliste parcourt 45 km en 2 h 30 min. Calculer sa vitesse moyenne.",r"$2$ h $30$ min $=2{,}5$ h. La vitesse moyenne est $45/2{,}5=\res{18\ \mathrm{km/h}}$.","Exprimer la durée dans l’unité du quotient.","assert 45/Rational('2.5')==18"),
E('Une conversion de vitesse',r"Convertir 72 km/h en m/s.",r"$72$ km correspondent à $72\,000$ m en 3600 s. Donc $72\,000/3600=\res{20\ \mathrm{m/s}}$. On retrouve $72/3{,}6=20$.","Convertir distance et durée.","assert Rational(72000,3600)==20"),
E('Un débit',r"Un robinet délivre 18 L en 45 s. Donner son débit en L/s.",r"Le débit vaut volume sur durée : $q=18/45=\res{0{,}4\ \mathrm{L/s}}$. Cela signifie 0,4 litre en une seconde dans le modèle à débit constant.","Diviser le volume par le temps.","assert Rational(18,45)==Rational('.4')"),
E('Un volume et une contenance',r"Convertir $0{,}35$ m$^3$ en litres et 250 mL en cm$^3$.",r"$0{,}35\times1000=\res{350}$ L. Comme 1 mL = 1 cm$^3$, $250$ mL $=\res{250\ \mathrm{cm}^3}$.","Utiliser les correspondances entre volume et contenance.","assert Rational('.35')*1000==350"),
E('Distance et temps',r"À vitesse constante de 12 km/h, quelle distance parcourt-on en 35 min ?",r"$35$ min $=35/60$ h. $d=v\times t=12\times35/60=\res7$ km. Une durée inférieure à une heure donne ici une distance inférieure à 12 km.","Multiplier la vitesse par la durée dans la bonne unité.","assert 12*Rational(35,60)==7"),
E('Remplir une cuve',r"Une cuve de 450 L est remplie à 15 L/min. Combien de temps faut-il ?",r"$t=V/q=450/15=\res{30}$ min. Contrôle : $15\times30=450$ L.","Diviser le volume par le débit.","assert Rational(450,15)==30"),
E('Changer les deux unités',r"Convertir $0{,}012$ m$^3$/s en L/min.",r"On convertit d’abord : $0{,}012$ m$^3$/s $=12$ L/s. En une minute, il s’écoule $12\times60=\res{720\ \mathrm{L/min}}$. Le temps est au dénominateur : une minute contient davantage de volume qu’une seconde.","Convertir séparément le numérateur et le temps de référence.","assert Rational('.012')*1000*60==720"),
E('Une concentration',r"On dissout 18 g de soluté dans une solution de volume final 300 mL. Calculer la concentration en g/L.",r"Le volume final vaut $0{,}300$ L. $c=m/V=18/0{,}3=\res{60\ \mathrm{g/L}}$. Le volume utilisé est celui de la solution finale, tel qu’il est donné.","Convertir le volume avant le quotient.","assert 18/Rational('.3')==60"),
E('Une énergie',r"Un appareil de 1,2 kW fonctionne pendant 45 min. Avec $E=P\times t$, calculer l’énergie en kWh.",r"$45$ min $=0{,}75$ h. Donc $E=1{,}2\times0{,}75=\res{0{,}9\ \mathrm{kWh}}$. La durée doit être en heures pour obtenir des kWh.","Associer chaque unité à la formule.","assert Rational('1.2')*Rational(45,60)==Rational('.9')"),
E('Aller et retour',r"Un trajet de 30 km est parcouru à 15 km/h à l’aller et à 30 km/h au retour. Calculer la vitesse moyenne sur l’ensemble.",r"L’aller dure $30/15=2$ h et le retour $30/30=1$ h. Pour 60 km en 3 h, la vitesse moyenne vaut $\res{20\ \mathrm{km/h}}$. La moyenne simple 22,5 ne tient pas compte des durées différentes.","Diviser la distance totale par la durée totale.","assert 60/(Rational(30,15)+Rational(30,30))==20"),
E('Une masse volumique',r"Une pièce a un volume de 40 cm$^3$ et une masse de 108 g. Calculer sa masse volumique, puis la masse d’une pièce de 65 cm$^3$ du même matériau.",r"$\rho=108/40=\res{2{,}7\ \mathrm{g/cm}^3}$. À masse volumique identique, $m=\rho V=2{,}7\times65=\res{175{,}5}$ g.","Calculer le quotient puis réutiliser le coefficient.","assert Rational(108,40)==Rational('2.7') and Rational(108,40)*65==Rational('175.5')"),
E('Deux arrivées d’eau',r"Deux robinets ont des débits constants de 8 et 12 L/min. Ils remplissent ensemble un bassin de 1,2 m$^3$, initialement vide, sans fuite. Donner le temps de remplissage.",r"Le volume vaut 1200 L. Les débits s’ajoutent : $8+12=20$ L/min. Donc $t=1200/20=\res{60}$ min, soit 1 h. Additionner les durées séparées serait incorrect.","Additionner les volumes fournis en une minute.","assert Rational(1200,8+12)==60"),
E('Une pause dans le trajet',r"Un marcheur parcourt 9 km à 4,5 km/h et fait une pause de 30 min. Quelle est sa vitesse moyenne si l’on inclut la pause ?",r"La marche dure $9/4{,}5=2$ h. La durée totale est 2,5 h. La vitesse moyenne vaut $9/2{,}5=\res{3{,}6\ \mathrm{km/h}}$. Elle est inférieure à la vitesse de marche car la pause ajoute du temps sans ajouter de distance.","Inclure tous les temps du bilan demandé.","assert 9/(9/Rational('4.5')+Rational(1,2))==Rational('3.6')"),
E('Une comparaison de débits',r"La pompe A débite 900 L/min ; B débite $0{,}018$ m$^3$/s. Laquelle est la plus rapide ? Combien de minutes gagne-t-elle pour 5400 L ?",r"B débite $0{,}018\times1000\times60=\res{1080}$ L/min, donc plus que A. A met $5400/900=6$ min ; B met $5400/1080=5$ min. Le gain est $\res1$ min.","Comparer dans une même unité puis calculer les durées.","assert Rational('.018')*1000*60==1080 and Rational(5400,900)-Rational(5400,1080)==1")
],reperes=['Vitesses, durées et distances','Débits et conversions composées','Concentration et masse volumique','Grandeurs produits et cohérence'],deco='calcul')

chapitre(9,'graphiques','Relier des grandeurs et lire des graphiques','2 · Algèbre et modèles',
'Tableaux · Formules · Courbes · Interprétation',
['Traduire une dépendance par une formule et un tableau.','Lire dans les deux sens sur un graphique.','Distinguer proportionnalité et autre relation.'],
['Repérage dans le plan et calcul littéral.'],[
r'''\essSection{1}{Trois représentations}
\begin{definition}Une grandeur peut dépendre d’une autre. Une formule donne une règle de calcul, un tableau donne des couples de valeurs, un graphique les représente. En Quatrième, on travaille ces correspondances sans formaliser les notations de fonctions.\end{definition}
\begin{exemple}Une location coûte 6 euros fixes puis 2 euros par heure. Pour une durée $t$ en heures, le prix est $P=6+2t$. Pour $t=0,1,2,3$, les prix sont $6,8,10,12$ euros. Ce n’est pas une proportionnalité car le prix n’est pas nul pour $t=0$.\end{exemple}
@FIG:cours-location@
\begin{savoirfaire}[Construire]Nommer et graduer les axes avec leurs unités. Placer la grandeur choisie sur l’axe horizontal. Calculer et placer plusieurs couples. Relier seulement si le contexte définit les valeurs intermédiaires, et avec une forme justifiée par la règle ou explicitée dans l’énoncé.\end{savoirfaire}''',
r'''\essSection{2}{Lire dans les deux sens}
\begin{savoirfaire}[De l’horizontale vers la verticale]Repérer une valeur sur l’axe horizontal, rejoindre la courbe verticalement, puis lire la valeur correspondante sur l’axe vertical. Dans l’autre sens, partir d’une valeur verticale et suivre une horizontale jusqu’à toutes les intersections avec la courbe.\end{savoirfaire}
\begin{exemple}Une température de four peut être atteinte à la montée et à la descente : la lecture inverse peut donner plusieurs durées. Une hauteur non atteinte n’a pas de durée correspondante dans l’intervalle représenté.\end{exemple}
\begin{propriete}Une proportionnalité se représente par une droite passant par l’origine. Une droite qui ne passe pas par l’origine représente une autre relation. Une courbe peut représenter une dépendance non proportionnelle, par exemple l’aire $A=c^2$ d’un carré de côté $c$.\end{propriete}
\begin{attention}Lire d’abord les graduations et les unités : une graduation peut valoir 2 minutes ou 20 degrés. Une lecture graphique est souvent approchée. Le graphique ne dit rien au-delà de la zone et des hypothèses précisées ; prolonger une tendance demande une justification.\end{attention}'''],[
E('Une formule de tarif',r"Une location coûte 5 euros fixes et 3 euros par heure. Exprimer le prix $P$ pour $t$ heures.",r"La partie fixe vaut 5 et la partie liée au temps vaut $3t$. Donc $\res{P=5+3t}$, avec $P$ en euros et $t$ en heures.","Additionner partie fixe et partie variable.","assert (5+3*x).subs(x,2)==11"),
E('Compléter les valeurs',r"Pour $P=5+3t$, calculer les prix pour $t=0$, $t=2$ et $t=4$.",r"On remplace $t$ dans la formule : pour 0 heure, le prix vaut 5 euros ; les deux autres prix valent $5+6=11$ et $5+12=17$. On retient $\res{5,\ 11,\ 17}$ euros, sans avoir besoin d’une notation de fonction.","Substituer chaque durée dans la même règle.","assert [5+3*a for a in [0,2,4]]==[5,11,17]"),
E('Lire un couple',r"Sur le graphique de température, lire la température à 2 min.",r"On part de 2 sur l’axe du temps, on rejoint le tracé puis on lit l’axe vertical : la température est $\res{60\,^\circ\mathrm C}$. Les unités viennent des axes.","Suivre la verticale puis l’horizontale.","assert 20+20*2==60",figure='four'),
E('Lire une durée',r"Sur le même graphique, à quel instant la température atteint-elle $100\,^\circ$C pour la première fois ?",r"L’horizontale de niveau 100 coupe le tracé à l’abscisse $\res4$ min pour la première fois. On lit un temps, et non une température.","Partir cette fois de l’axe vertical.","assert 20+20*4==100",figure='four'),
E('Reconnaître une relation',r"Le graphique représente-t-il une situation proportionnelle ? Justifier.",r"La droite représentée passe par $(0;2)$, pas par l’origine. La relation n’est donc pas proportionnelle, même si les points sont alignés. Pour zéro unité horizontale, la valeur verticale est déjà 2.","Vérifier le passage par l’origine.","assert (2+2*x).subs(x,0)==2",figure='graph-non-proportion'),
E('Construire un graphique',r"On vend une corde à 1,5 euro par mètre, pour des longueurs de 0 à 6 m. Compléter un tableau pour 0, 2, 4 et 6 m, puis tracer la représentation.",r"Les prix sont $\res{0,\ 3,\ 6,\ 9}$ euros. Les points $(0;0)$, $(2;3)$, $(4;6)$ et $(6;9)$ s’alignent avec l’origine. La corde pouvant être achetée en longueur intermédiaire dans ce modèle, on trace le segment correspondant.","Placer les couples avant de relier.","assert [Rational('1.5')*a for a in [0,2,4,6]]==[0,3,6,9]",figure='graph-corde'),
E('Une lecture inverse double',r"Sur le graphique de température, donner tous les instants où la température vaut $60\,^\circ$C.",r"La droite horizontale de niveau 60 coupe le tracé deux fois : à $\res2$ min pendant la chauffe et à $\res{10}$ min pendant le refroidissement. Il faut chercher toutes les intersections dans l’intervalle représenté.","Parcourir toute l’horizontale.","assert 20+20*2==60 and 160-10*10==60",figure='four'),
E('Aire d’un carré',r"Exprimer l’aire $A$ d’un carré de côté $c$ cm. Calculer pour $c=1,2,3,4$. Y a-t-il proportionnalité ?",r"$A=c^2$. Les aires valent $\res{1,4,9,16}$ cm$^2$. Doubler le côté de 1 à 2 multiplie l’aire par 4 et non par 2 : l’aire n’est pas proportionnelle au côté.","Comparer un doublement de la grandeur de départ.","assert [a*a for a in [1,2,3,4]]==[1,4,9,16]",figure='graph-carre'),
E('Une formule à retrouver',r"Un tableau donne les couples $(0;4)$, $(1;7)$, $(2;10)$ et $(3;13)$. On sait que le modèle est un montant fixe plus 3 fois la première valeur. Écrire la formule.",r"Pour une première valeur $x$, le montant est $3x+b$. Le couple $(0;4)$ donne $b=4$. La formule est $\res{P=3x+4}$. Elle retrouve les trois autres couples. Sans l’hypothèse sur le modèle, le tableau seul ne fixerait pas une règle unique.","Utiliser la valeur pour zéro et la règle annoncée.","assert [3*a+4 for a in [0,1,2,3]]==[4,7,10,13]"),
E('Un tableur',r"Dans un tableur, A2 contient une durée en heures. Quelle formule saisir en B2 pour le prix $P=5+3t$, puis recopier vers le bas ?",r"On saisit $\res{\texttt{=5+3*A2}}$. Lors de la recopie, A2 devient A3, A4, etc. La référence relative suit la durée de chaque ligne ; les nombres 5 et 3 restent fixes.","Remplacer la lettre par la cellule de la ligne.","assert 5+3*4==17",figure='tableur-prix'),
E('Retirer des carrés',r"Dans un rectangle de 18 cm sur 10 cm, on retire aux quatre coins des carrés de côté $x$ cm, avec $0<x<5$. Exprimer l’aire restante et la calculer pour $x=2$.",r"L’aire initiale vaut 180 cm$^2$. Les quatre carrés retirent $4x^2$, donc $\res{A=180-4x^2}$. Pour $x=2$, $A=180-16=\res{164\ \mathrm{cm}^2}$. La condition $x<5$ empêche les carrés des deux bords courts de se chevaucher.","Soustraire les quatre aires retirées.","assert (180-4*x**2).subs(x,2)==164",figure='coins-retires'),
E('Deux courbes de prix',r"Les graphiques correspondent aux prix A $=4+2t$ et B $=4t$, pour $0\le t\le4$ h. Lire l’heure d’égalité et vérifier par une équation.",r"Les tracés se coupent au point $(2;8)$. L’égalité $4+2t=4t$ donne $4=2t$, donc $\res{t=2}$ h et un prix de $\res8$ euros. Avant 2 h, B est moins cher ; après 2 h, A est moins cher sur l’intervalle étudié.","Confirmer la lecture par le calcul.","assert solve(4+2*x-4*x,x)==[2]",figure='graph-tarifs'),
E('Une réserve qui diminue',r"Une réserve contient 120 L ; on retire 8 L par minute à débit constant. Donner une formule pour le volume après $t$ minutes et la durée de validité avant épuisement.",r"Le volume restant est $\res{V=120-8t}$ L. Il atteint zéro pour $120-8t=0$, soit $t=15$ min. Le modèle de vidange est valable pour $\res{0\le t\le15}$ ; un volume négatif ne représente pas la situation.","Associer une formule à un domaine physique.","assert solve(120-8*x,x)==[15]",figure='graph-reserve'),
E('Connaître les limites',r"Un graphique ne montre que les ventes de janvier à juin. Peut-on affirmer que les ventes de décembre seront égales au double de celles de juin si le tracé monte ?",r"Non. Une tendance sur l’intervalle janvier-juin ne fixe pas la suite. Il manque les données ou un modèle justifié pour décembre. Même une hausse régulière dans la zone observée ne prouve pas qu’elle continuera.","Distinguer données observées et prolongement supposé.","assert 6<12"),
E('Comparer deux dépendances',r"Un carré de côté $c$ cm a un périmètre $P=4c$ et une aire $A=c^2$. Pour quels côtés positifs leur valeur numérique est-elle la même ? Chercher un exemple, puis justifier sans résoudre d’équation du second degré.",r"Pour $c=4$, $P=16$ et $A=16$. Si $c>0$, l’égalité numérique $c\times c=4c$ peut être divisée par $c$, non nul : on obtient $\res{c=4}$ seulement. Les unités restent différentes, cm et cm$^2$ ; on compare des valeurs numériques.","Utiliser la positivité pour diviser par le côté.","assert 4*4==4**2 and simplify((x*x-4*x)/x)==x-4",figure='carre-4')
],reperes=['Formules et tableaux de valeurs','Lecture graphique dans les deux sens','Construction et proportionnalité','Interprétation, tableur et domaine'],deco='courbe')
